{
  "kc_id": "KC_CLF_DT_001",
  "canonical_name": "Hunt's Algorithm",
  "definition": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "Hunt's algorithm is used to fit training data by starting with a single leaf node and recursively splitting training instances based on attribute test conditions to create a tree.",
    "supporting_evidence_ids": [
      "E4",
      "E5"
    ],
    "supporting_lanes": [
      "context_lane"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "Leaf nodes are expanded if they contain training instances from more than one class, though child nodes may be empty if no training instances possess the required attribute values.",
    "supporting_evidence_ids": [
      "E3",
      "E4"
    ],
    "supporting_lanes": [
      "scope_lane",
      "context_lane"
    ],
    "abstention_reason": ""
  }
}

