{
  "kc_id": "KC_CLF_DT_005",
  "canonical_name": "Entropy (Node)",
  "definition": {
    "status": "grounded",
    "grounding_mode": "single_strong_context",
    "text": "Entropy of an interval is a measure of its purity; it is 0 if the interval is perfectly pure (containing only values of one class) and reaches a maximum if the classes of values in the interval occur equally often.",
    "supporting_evidence_ids": [
      "E3"
    ],
    "supporting_lanes": [
      "scope_lane"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "grounding_mode": "direct_scope",
    "text": "Entropy-based approaches are used for discretization, whether bottom-up or top-down. The total entropy of a partition is the weighted average of the individual interval entropies.",
    "supporting_evidence_ids": [
      "E3"
    ],
    "supporting_lanes": [
      "scope_lane"
    ],
    "abstention_reason": ""
  }
}

