{
  "kc_id": "KC_CLU_EVAL_002",
  "canonical_name": "SSE (Cluster Quality)",
  "definition": {
    "status": "grounded",
    "grounding_mode": "single_strong_context",
    "text": "The sum of the squared error (SSE), also known as scatter, is calculated by computing the Euclidean distance from each data point to its closest centroid and then summing the squares of these errors.",
    "supporting_evidence_ids": [
      "E2"
    ],
    "supporting_lanes": [
      "context_lane"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "SSE is used as an objective function to measure clustering quality; a lower SSE indicates that the centroids are a better representation of the points in their cluster and translates to better clustering results.",
    "supporting_evidence_ids": [
      "E2",
      "E3"
    ],
    "supporting_lanes": [
      "context_lane",
      "scope_lane"
    ],
    "abstention_reason": ""
  }
}

{
  "kc_id": "KC_CLU_EVAL_003",
  "canonical_name": "Cohesion",
  "definition": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "Cohesion, also referred to as compactness, is a cluster evaluation measure that can be quantified via SSE, centroid-based measures, or a graph-based view as the sum of the weights of the links in the proximity graph that connect points within a cluster.",
    "supporting_evidence_ids": [
      "E6",
      "E4",
      "E7",
      "E2"
    ],
    "supporting_lanes": [
      "scope_lane",
      "context_lane"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "grounding_mode": "direct_scope",
    "text": "When used with partitional clustering algorithms such as K-means, cohesion is typically incorporated with separation to provide a way to determine the number of clusters.",
    "supporting_evidence_ids": [
      "E6"
    ],
    "supporting_lanes": [
      "scope_lane"
    ],
    "abstention_reason": ""
  }
}

{
  "kc_id": "KC_CLU_EVAL_004",
  "canonical_name": "Separation",
  "definition": {
