  "canonical_name": "Silhouette Coefficient",
  "definition": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "An internal clustering validity index computed for unlabeled data that serves as a measure of the goodness of a clustering.",
