{
  "kc_id": "KC_CLU_HIER_001",
  "canonical_name": "Dendrogram",
  "definition": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "A dendrogram is a diagram that displays cluster-subcluster relationships, where the height at which two clusters are merged reflects the distance between them.",
    "supporting_evidence_ids": [
      "E3",
      "E2"
    ],
    "supporting_lanes": [
      "definition_lane",
      "context_lane"
