  "scope": {
    "status": "grounded",
    "grounding_mode": "direct_scope",
    "text": "In hierarchical clustering, a dendrogram can be used to generate K clusters by taking the clusters at a specific level of the diagram.",
    "supporting_evidence_ids": [
      "E6"
    ],
    "supporting_lanes": [
      "scope_lane"
    ],
    "abstention_reason": ""
