}

{
  "kc_id": "KC_CLU_HIER_004",
  "canonical_name": "MIN (Single Linkage)",
  "definition": {
    "status": "grounded",
    "grounding_mode": "direct_definition",
    "text": "In the MIN (Single Linkage) version of hierarchical clustering, the proximity of two clusters is defined as the minimum distance (or maximum similarity) between any two points in the two different clusters.",
