{
  "kc_id": "KC_CLU_HIER_005",
  "canonical_name": "MAX (Complete Linkage)",
  "definition": {
    "status": "grounded",
    "grounding_mode": "direct_definition",
    "text": "In hierarchical clustering, the MAX (complete link) method defines the proximity between two clusters as the maximum distance (or minimum similarity) between any two points in the two different clusters.",
    "supporting_evidence_ids": [
      "E2"
    ],
    "supporting_lanes": [
      "definition_lane"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "The complete link method favors globular shapes and is less susceptible to noise and outliers, although it can break large clusters. It is applied by calculating the maximum distance between any two points in the clusters, and in graph terms, a group of points is not a cluster until all points in it form a clique.",
    "supporting_evidence_ids": [
      "E2",
      "E3"
    ],
    "supporting_lanes": [
      "definition_lane",
      "context_lane"
    ],
    "abstention_reason": ""
  }
}

{
  "kc_id": "KC_CLU_HIER_006",
  "canonical_name": "Group Average Linkage",
  "definition": {
    "status": "grounded",
    "grounding_mode": "single_strong_context",
    "text": "In the group average version of hierarchical clustering, the proximity of two clusters is defined as the average pairwise proximity among all pairs of points in the different clusters.",
    "supporting_evidence_ids": [
      "E5"
    ],
    "supporting_lanes": [
      "context_lane"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "grounding_mode": "single_strong_context",
    "text": "This is an intermediate approach between the single and complete link approaches.",
    "supporting_evidence_ids": [
      "E5"
    ],
    "supporting_lanes": [
      "context_lane"
    ],
    "abstention_reason": ""
  }
}

{
  "kc_id": "KC_CLU_HIER_007",
  "canonical_name": "Ward's Method",
  "definition": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "Ward's method is a clustering technique that assumes clusters are represented by centroids and defines the proximity between two clusters as the increase in the sum of squared errors (SSE) that results from merging them, aiming to minimize the sum of squared distances of points from their cluster centroids.",
    "supporting_evidence_ids": [
      "E2",
      "E7"
    ],
    "supporting_lanes": [
      "context_lane",
      "scope_lane"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "Ward's method is often used as a robust method for initializing K-means clustering. It is sensitive to outliers, which increase SSE and distort centroids. Additionally, it is mathematically similar to the group average method when the proximity between two points is the square of the distance between them.",
    "supporting_evidence_ids": [
      "E1",
      "E4",
      "E5"
    ],
    "supporting_lanes": [
      "scope_lane",
      "context_lane"
    ],
    "abstention_reason": ""
  }
}

{
  "kc_id": "KC_CLU_HIER_008",
  "canonical_name": "Hierarchical Clustering Complexity",
  "definition": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "The computational complexity of hierarchical clustering, which can be O(m^3) or O(m^2 log m) depending on the implementation (such as the use of sorted lists or heaps), making the process computationally expensive.",
    "supporting_evidence_ids": [
      "E1",
      "E3"
    ],
    "supporting_lanes": [
      "scope_lane",
      "context_lane"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "grounding_mode": "direct_scope",
    "text": "Hierarchical clustering is practical only if the sample size is relatively small (e.g., a few hundred to a few thousand) and K is relatively small compared to the sample size.",
    "supporting_evidence_ids": [
      "E1"
    ],
    "supporting_lanes": [
      "scope_lane"
    ],
    "abstention_reason": ""
  }
}

